export function formatComicDomainError(messageKey: string, params: Readonly<Record<string, string | number | boolean | null>> = {}, locale = "en"): string | undefined {
  if (!Object.prototype.hasOwnProperty.call(reasons, messageKey)) return undefined;
  const language = locale.toLowerCase().replace(/_/g, "-");
  const normalized = /^zh-(?:tw|hk|hant)(?:-|$)/.test(language) ? "zh-TW" : /^zh(?:-|$)/.test(language) ? "zh-CN"
    : /^pt(?:-|$)/.test(language) ? "pt-BR" : language.split("-")[0];
  const index = COMIC_ERROR_LOCALES.indexOf(normalized as typeof COMIC_ERROR_LOCALES[number]);
  const row = messages[reasons[messageKey]];
  const text = row[index < 0 ? 0 : index].replace(/\{([A-Za-z][A-Za-z0-9]*)\}/g, (_, key: string) => {
    const value = params[key];
    return typeof value === "number" && Number.isFinite(value) ? String(value)
      : typeof value === "string" ? value.slice(0, 240) : "—";
  });
  // Field paths are protocol identifiers, never inferred from or used to translate authored content.
  const field = typeof params.field === "string" && /^[A-Za-z][A-Za-z0-9_.[\]-]{0,199}$/.test(params.field) ? params.field : undefined;
  return field ? `${text} (${field})` : text;
}
